def refazer_localizacoes_antigas(apps, schema_editor):
    """Descarta o cache de CEP gravado pela regra antiga e manda os candidatos de volta para a fila de localização.

    A regra antiga aceitava a coordenada da BrasilAPI, que para os CEPs do Rio de Janeiro é sempre o centro da cidade
    (Guadalupe aparecia no Centro), e a busca no Nominatim sem conferir o bairro. Os pontos já gravados nos candidatos
    ficam como estão até o worker recalculá-los (alguns minutos).
    """
    GeoCache = apps.get_model('core', 'GeoCache')
    Candidato = apps.get_model('candidatos', 'Candidato')
    antigos = GeoCache.objects.filter(fonte__in=('brasilapi', 'nominatim'))
    Candidato.objects.filter(cep__in=antigos.values('cep')).update(geo_status='pendente')
    antigos.delete()


